<?php
declare(strict_types=1);
define('XAR_SPECIAL_FIXTURE_ONLY',true);require __DIR__.'/tactical-special-effects.php';$specialChecks=0;$db=specialFixture();
$template=['id'=>'copy-model','name'=>'Potion à copier','kind'=>'potion','potion'=>['hp'=>5,'mana'=>0,'fatigue'=>0],'permissions'=>['destroy'=>true],'size'=>40,'maxHp'=>20];
$source=['id'=>'copy-source','templateId'=>$template['id'],'revision'=>8,'name'=>'Étiquette propre','description'=>'Texte propre','size'=>80,'health'=>['current'=>7,'max'=>20],'location'=>['kind'=>'ground','sceneId'=>'scene-one','layerId'=>'ground','x'=>30,'y'=>40]];
$db->put('items',normalizeItemStore(['version'=>1,'templates'=>[$template],'instances'=>[$source]]));$before=$db->payload('items');$character=$db->payload('character:character-player');
$args=['sceneId'=>'scene-one','requestId'=>'copy-native-'.randomToken(16),'itemId'=>'new-copy','templateId'=>$template['id'],'copyFromItemId'=>$source['id'],'expectedCopyRevision'=>8,'location'=>[...$source['location'],'x'=>60,'y'=>50]];
specialCheck(runCommand($db,'item.spawn',$args)->status===403,'Player cannot create a copy');$first=runCommand($db,'item.spawn',$args,true);specialCheck($first->status===200,'GM copy accepted: '.json_encode($first->body));$items=$db->payload('items');specialCheck(count($items['instances'])===2,'Exactly one new instance');specialCheck($items['instances'][0]===$before['instances'][0],'Source fields and revision intact');specialCheck($items['instances'][1]===[...$before['instances'][0],'id'=>'new-copy','revision'=>1,'location'=>$args['location']],'Independent identity and copied overrides');specialCheck($items['templates']===$before['templates'],'No new model');specialCheck($db->payload('character:character-player')===$character,'No character mutation');
specialCheck((runCommand($db,'item.spawn',$args,true)->body['deduplicated']??false)===true,'ACK is idempotent');
foreach([['expectedCopyRevision'=>7],['location'=>[...$args['location'],'layerId'=>'upper']]] as $invalid)specialCheck(runCommand($db,'item.spawn',[...$args,'itemId'=>'invalid-copy','requestId'=>'invalid-copy-'.randomToken(16),...$invalid],true)->status===409,'Invalid source or layer rejected');
$map=$db->payload('map:scene-one');$map['activeLayerId']='upper';$db->put('map:scene-one',$map);specialCheck(runCommand($db,'item.spawn',[...$args,'itemId'=>'stale-layer-copy','requestId'=>'stale-copy-'.randomToken(16)],true)->status===409,'Stale active layer rejected');specialCheck(count($db->payload('items')['instances'])===2,'Rejected copies create no items');
fwrite(STDOUT,json_encode(['ok'=>true,'checks'=>$specialChecks],JSON_UNESCAPED_UNICODE)."\n");
